"""Render the saved actual comparison; this does not execute the model."""
import hashlib
import html
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
raw=(ROOT/'result.json').read_bytes();r=json.loads(raw)
rows=''.join(f"<tr><th>{html.escape(name)}</th><td>{v['logits']['max_abs_error']:.3e}</td><td>{v['loss']['max_abs_error']:.3e}</td><td>{max(x['max_abs_error'] for x in v['parameter_gradients'].values()):.3e}</td></tr>" for name,v in r['comparisons'].items())
probes=''.join(f"<li><b>{html.escape(name.replace('_',' '))}</b><span>Logit difference {v['max_abs_error']:.3e}; within tolerance: {str(v['passed']).lower()}</span></li>" for name,v in r['failures']['mismatch_probes'].items())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Actual CPU transformer comparison</title><style>*{box-sizing:border-box}body{margin:0;background:#fff;color:#192136;font:18px/1.5 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:32px}h1{font-size:32px;line-height:1.2}p{color:#596375}table{width:100%;border-collapse:collapse;font-size:17px}th,td{text-align:left;border-bottom:1px solid #dfe4ed;padding:12px 8px}td{font-family:monospace}ul{padding:0;list-style:none}li{border-top:1px solid #dfe4ed;padding:14px 0}li span{display:block;color:#596375}code{overflow-wrap:anywhere}a{color:#274bc4}@media(max-width:600px){main{padding:18px}h1{font-size:26px}table,tbody,tr,td,th{display:block}thead{display:none}td{padding:5px 0;border:0}tr{padding:12px 0;border-bottom:1px solid #dfe4ed}td:nth-child(2):before{content:'Logits: '}td:nth-child(3):before{content:'Loss: '}td:nth-child(4):before{content:'Gradients: '}}</style><main><p>Actual saved run · CPU float64</p><h1>Three implementations, one numerical check</h1><p>Unchanged list transformer compared with explicit PyTorch attention and the SDPA math backend. Five positions, one head, dropout zero.</p><h2>Maximum absolute errors</h2><table><thead><tr><th>Path vs handwritten</th><th>Logits</th><th>Loss</th><th>Parameter gradients</th></tr></thead><tbody>ROWS</tbody></table><p>COUNTS<br>Acceptance: |actual − reference| ≤ 1e−10 + 1e−8 × |reference|.</p><h2>Deliberate mismatches</h2><ul>PROBES</ul><p>REFUSED malformed input cases refused. These are numerical comparisons and fault probes, not a training or throughput benchmark.</p><p><a href="result.json">Raw result</a> · <a href="run-output.txt">Command output</a></p><p>Result SHA-256: <code>DIGEST</code></p></main></html>'''
(ROOT/'report.html').write_text(page.replace('ROWS',rows).replace('PROBES',probes).replace('DIGEST',hashlib.sha256(raw).hexdigest()).replace('COUNTS',f"All {len(r['comparisons']['explicit']['parameter_gradients'])} parameter tensors / {r['comparisons']['explicit']['compared_gradient_elements']} gradient elements compared.").replace('REFUSED',str(len(r['failures']['refused_inputs']))))
